  const dot = body.indexOf('.');
  const intPart = dot === -1 ? body : body.slice(0, dot);
  const decPart = dot === -1 ? '' : body.slice(dot + 1);
  if (!/^\d+$/.test(intPart)) return s;
  // separators per named style — a table, not a ternary chain (S3358)
  const SEPS: Record<string, { g: string; d: string }> = {
    dot: { g: '.', d: ',' },
    space: { g: ' ', d: '.' },
  };
  const { g: gsep, d: dsep } = SEPS[style ?? ''] ?? { g: ',', d: '.' };
