export function fmt(v: string, ops: Array<[string, string?]>): string {
  let s = v;
  for (const [op, arg] of ops) {
    const arith = ARITH[op];
    if (arith) {
      const n = Number(s);
      // arithmetic on a non-number yields '' — never NaN on screen
      s = Number.isNaN(n) ? '' : arith(n, Number(arg ?? 0));
      continue;
    }
    const fn = OPS[op];
    if (fn) s = fn(s, arg);
  }
  return s;
}
